var version="dev"
func main(){ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer stop();dbPath:=env("RUNNERHUB_DB","runnerhub.db");st,err:=store.OpenSQLite(dbPath);must(err);defer st.Close();must(migrateLegacyRunnerPools(ctx,st));enroll:=mustEnv("RUNNERHUB_ENROLLMENT_TOKEN");agentSecret:=mustEnv("RUNNERHUB_AGENT_SECRET");hub,err:=agenthub.New(st,enroll,agentSecret);must(err);metrics:=&telemetry.Metrics{};appSlug:=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_APP_SLUG"));appClientID:=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_APP_CLIENT_ID"));if appClientID==""{appClientID=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_APP_ISSUER"))};appIssuer:=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_APP_ID"));if appIssuer==""{appIssuer=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_APP_ISSUER"))};var gh githubrunner.Backend;var catalog githubrunner.Catalog;if appIssuer!=""{apiURL:=env("RUNNERHUB_GITHUB_API_URL","https://api.github.com");key,err:=os.ReadFile(mustEnv("RUNNERHUB_GITHUB_APP_PRIVATE_KEY_FILE"));must(err);tokens,err:=githubrunner.NewGitHubAppTokenSource(githubrunner.GitHubAppConfig{Issuer:appIssuer,AppSlug:appSlug,PrivateKeyPEM:key,BaseURL:apiURL});must(err);gh,err=githubrunner.NewHTTPBackendWithBaseURL(nil,tokens,apiURL);must(err);catalog,err=githubrunner.NewHTTPCatalog(nil,tokens,apiURL);must(err)};var githubBrowser *githubauth.Manager;clientSecret:=strings.TrimSpace(os.Getenv("RUNNERHUB_GITHUB_CLIENT_SECRET"));publicURL:=strings.TrimSpace(os.Getenv("RUNNERHUB_PUBLIC_URL"));if clientSecret!=""||publicURL!=""{if appClientID==""||clientSecret==""||appSlug==""||publicURL==""{log.Fatal("GitHub browser auth requires RUNNERHUB_GITHUB_APP_CLIENT_ID (or legacy RUNNERHUB_GITHUB_APP_ISSUER), RUNNERHUB_GITHUB_CLIENT_SECRET, RUNNERHUB_GITHUB_APP_SLUG, and RUNNERHUB_PUBLIC_URL")};githubBrowser,err=githubauth.New(githubauth.Config{ClientID:appClientID,ClientSecret:clientSecret,AppSlug:appSlug,PublicURL:publicURL,APIURL:env("RUNNERHUB_GITHUB_API_URL","https://api.github.com"),StateDir:env("RUNNERHUB_GITHUB_AUTH_STATE_DIR",filepath.Dir(dbPath))});must(err)};allowed:=map[string]struct{}{};for _,x:=range strings.Split(env("RUNNERHUB_ALLOWED_IMAGES",images.DefaultRunnerImage),","){if x=strings.TrimSpace(x);x!=""{allowed[x]=struct{}{}}};var cacheStore *cachepkg.Store;if root:=os.Getenv("RUNNERHUB_CACHE_DIR");root!=""{cacheStore=&cachepkg.Store{Root:root,MaxBytes:int64Env("RUNNERHUB_CACHE_MAX_OBJECT_BYTES",8<<30)}};var sessionAuth auth.SessionAuthenticator;if githubBrowser!=nil{sessionAuth=githubBrowser.Authenticate};authm:=auth.New(auth.Config{APIKeys:auth.ParseKeys(os.Getenv("RUNNERHUB_API_KEYS")),TrustOIDCHeaders:boolEnv("RUNNERHUB_TRUST_OIDC_HEADERS",false),SessionAuthenticator:sessionAuth});svc:=&apihttp.Service{Store:st,GitHub:gh,Catalog:catalog,GitHubAuth:githubBrowser,Hub:hub,Scheduler:scheduler.Scheduler{Store:st},Policy:policy.Engine{AllowedImages:allowed,MaxResources:core.Resources{CPUMillis:64000,MemoryBytes:256<<30},RequirePinnedImages:boolEnv("RUNNERHUB_REQUIRE_PINNED_IMAGES",true),AllowPrivileged:boolEnv("RUNNERHUB_ALLOW_PRIVILEGED_WORKERS",false)},Metrics:metrics,Auth:authm,Cache:cacheStore,Static:webui.Handler(),MachineBootstrap:machinebootstrap.SSH{},MachineBootstrapURL:publicURL,MachineAgentImage:env("RUNNERHUB_MACHINE_AGENT_IMAGE","ghcr.io/eutelic/runnerhub-agent:latest"),DeployerBootstrap:&deployer.BootstrapManager{Root:env("RUNNERHUB_DEPLOYER_BOOTSTRAP_ROOT","/data/deployer-bootstrap")}};hub.SetResultHandler(svc.HandleAgentResult);rec:=&reconcile.Reconciler{Store:st,GitHub:gh,Hub:hub,Interval:15*time.Second};go func(){if err:=rec.Run(ctx);err!=nil&&ctx.Err()==nil{log.Printf("reconciler stopped: %v",err)}}();if ciGH,ok:=gh.(githubrunner.CIMetadataBackend);ok{ciStatus:=cireconcile.NewStatus(cireconcile.DefaultAnalyticsLookback);svc.CIReconcilerStatus=ciStatus;ciRec:=&cireconcile.Reconciler{Store:st,GitHub:ciGH,Interval:time.Minute,Lookback:cireconcile.DefaultAnalyticsLookback,Status:ciStatus};go func(){if err:=ciRec.Run(ctx);err!=nil&&ctx.Err()==nil{log.Printf("CI reconciler stopped: %v",err)}}()};addr:=env("RUNNERHUB_HTTP_ADDR","127.0.0.1:8080");certFile:=strings.TrimSpace(os.Getenv("RUNNERHUB_TLS_CERT_FILE"));keyFile:=strings.TrimSpace(os.Getenv("RUNNERHUB_TLS_KEY_FILE"));if (certFile=="")!=(keyFile==""){log.Fatal("RUNNERHUB_TLS_CERT_FILE and RUNNERHUB_TLS_KEY_FILE must be set together")};if certFile==""&&!isLoopbackBind(addr)&&!boolEnv("RUNNERHUB_ALLOW_INSECURE_HTTP",false){log.Fatal("non-loopback RunnerHub HTTP requires TLS; configure RUNNERHUB_TLS_CERT_FILE/RUNNERHUB_TLS_KEY_FILE or explicitly set RUNNERHUB_ALLOW_INSECURE_HTTP=true only on a separately protected network")};server:=&http.Server{Addr:addr,Handler:svc.Handler(),ReadHeaderTimeout:5*time.Second,IdleTimeout:90*time.Second,MaxHeaderBytes:1<<20,TLSConfig:&tls.Config{MinVersion:tls.VersionTLS12}};go func(){<-ctx.Done();shutdown,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();_=server.Shutdown(shutdown)}();scheme:="http";if certFile!=""{scheme="https"};log.Printf("runnerhub %s listening on %s://%s",version,scheme,addr);if certFile!=""{err=server.ListenAndServeTLS(certFile,keyFile)}else{err=server.ListenAndServe()};if err!=nil&&err!=http.ErrServerClosed{log.Fatal(err)}}
func migrateLegacyRunnerPools(ctx context.Context,st *store.SQLite)error{pools,err:=st.ListPools(ctx);if err!=nil{return err};byID:=map[string]core.RunnerPool{};for _,p:=range pools{next,changed:=images.UpgradeLegacyDefault(p.Image);if changed{old:=p.Image;p.Image=next;if err:=st.UpsertPool(ctx,p);err!=nil{return err};_ = st.AppendAudit(ctx,core.AuditEvent{Actor:"system",Action:"migrate_runner_image",ResourceType:"pool",ResourceID:p.ID,Result:"ok",SafeDetail:old+" -> "+next});log.Printf("migrated pool %s from legacy moving runner image to immutable default",p.ID)};byID[p.ID]=p};workers,err:=st.ListWorkers(ctx);if err!=nil{return err};for _,w:=range workers{if w.Isolation!=""{continue};p,ok:=byID[w.PoolID];if !ok||p.Isolation==""{continue};w.Isolation=p.Isolation;if err:=st.UpsertWorker(ctx,w);err!=nil{return err};_ = st.AppendAudit(ctx,core.AuditEvent{Actor:"system",Action:"migrate_worker_isolation",ResourceType:"worker",ResourceID:w.ID,Result:"ok",SafeDetail:string(w.Isolation)})};return nil}
func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d}
func mustEnv(k string)string{v:=strings.TrimSpace(os.Getenv(k));if v==""{log.Fatalf("%s is required",k)};return v}
func boolEnv(k string,d bool)bool{v:=strings.TrimSpace(os.Getenv(k));if v==""{return d};b,err:=strconv.ParseBool(v);if err!=nil{log.Fatalf("%s must be true or false",k)};return b}
func int64Env(k string,d int64)int64{v:=strings.TrimSpace(os.Getenv(k));if v==""{return d};n,err:=strconv.ParseInt(v,10,64);if err!=nil||n<=0{log.Fatalf("%s must be a positive integer",k)};return n}
func isLoopbackBind(addr string)bool{host,_,err:=net.SplitHostPort(addr);if err!=nil{return false};if strings.EqualFold(host,"localhost"){return true};ip:=net.ParseIP(host);return ip!=nil&&ip.IsLoopback()}
func must(err error){if err!=nil{log.Fatal(err)}}
